//! Output parity between the transcript post-processing in `voxr_narrate`
//! and the JavaScript it ports.
//!
//! The fixture (`tests/fixtures/narration_transcript_oracle.json`) was
//! generated by `tests/tools/narration_oracle/transcript_oracle.mjs`. Each
//! case carries its inputs: word lists as numbers, and signals as the
//! `signals.mjs` ops that `common::signals` builds bit for bit, with each
//! signal's FNV-1a hash. The transcribe cases ran the JavaScript pipeline
//! with a recognizer that returns scripted words per piece; the port runs
//! with a [`Transcriber`] returning the same words. Output times are
//! JavaScript's `String(x)` and compare exactly, and each file the
//! transcribe command writes compares byte for byte.

use std::path::{Path, PathBuf};

use voxr_narrate::{
    self as narration, HeardWord, NarrationManifest, PhraseGroups, SceneNarration, TimelineWords,
    TranscribeOptions, Transcriber, Voiceover, WordsFile,
};

mod common;
use common::signals;
use common::transcript_cases::{Compose, Fixture, NarrationOut, OutWord, cues, render};
use common::{assert_oracle_current, check, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_transcript_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/transcript_oracle.mjs"
);
/// The model the oracle names in every words file.
const MODEL: &str = "onnx-community/whisper-base_timestamped";

/// A number as `{:?}`, -0 as 0, so the exact doubles compare as text.
fn exact(v: f64) -> String {
    format!("{:?}", v + 0.0)
}

fn word_text(text: &str, start: f64, end: f64) -> String {
    format!("{text} {} {}", exact(start), exact(end))
}

/// Records every difference between the port's words and the fixture's.
fn check_words(diffs: &mut Vec<String>, what: &str, got: &[HeardWord], want: &[OutWord]) {
    let got: Vec<String> = got
        .iter()
        .map(|w| word_text(&w.text, w.start, w.end))
        .collect();
    let want: Vec<String> = want
        .iter()
        .map(|w| word_text(&w.text, num(&w.start), num(&w.end)))
        .collect();
    check(diffs, what, format!("{got:?}"), format!("{want:?}"));
}

fn report(what: &str, diffs: &[String]) {
    assert!(
        diffs.is_empty(),
        "{what}: {} differences:\n{}",
        diffs.len(),
        diffs.join("\n")
    );
}

/// Returns each piece's scripted words, and records every call.
struct Scripted<'a> {
    script: &'a [Vec<(String, f64, Option<f64>)>],
    calls: Vec<(usize, u32, Option<String>, String)>,
}

impl Transcriber for Scripted<'_> {
    fn transcribe_words(
        &mut self,
        samples: &[f32],
        sample_rate: u32,
        language: Option<&str>,
    ) -> narration::Result<Vec<HeardWord>> {
        let call = self.calls.len();
        self.calls.push((
            samples.len(),
            sample_rate,
            language.map(str::to_string),
            signals::fnv1a(samples),
        ));
        Ok(self
            .script
            .get(call)
            .map(|words| {
                words
                    .iter()
                    .map(|(text, start, end)| HeardWord {
                        text: text.clone(),
                        start: *start,
                        end: end.unwrap_or(f64::NAN),
                    })
                    .collect()
            })
            .unwrap_or_default())
    }
}

#[test]
fn fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}

#[test]
fn constants_match() {
    let f: Fixture = load_json(Path::new(FIXTURE));
    assert_eq!(num(&f.constants.audio_lead), narration::AUDIO_LEAD);
    assert_eq!(num(&f.constants.audio_tail), narration::AUDIO_TAIL);
}

/// The transcribe command's script step: the script's words on the heard
/// timings, settled on the audio.
fn compose(file: &mut WordsFile, x: &[f32], c: &Compose) -> narration::Result<()> {
    let heard = file.words.clone();
    let words = match &c.phrases {
        Some(phrases) => {
            let spans = cues(phrases);
            let placed = narration::align_phrases(&heard, &spans)?;
            let mut words = placed.words.clone();
            narration::fit_file(&mut words, x, Some(placed.groups(&spans)))?;
            words
        }
        None => {
            let mut words = narration::align_script(&heard, c.script.as_deref().unwrap_or(""))?;
            narration::fit_file(&mut words, x, None)?;
            words
        }
    };
    file.heard = Some(heard);
    file.words = words;
    file.phrases = c.phrases_file.clone();
    file.script = Some(c.script_file.clone());
    Ok(())
}

#[test]
fn transcribe_matches_javascript() -> narration::Result<()> {
    let f: Fixture = load_json(Path::new(FIXTURE));
    let mut diffs = Vec::new();
    for case in &f.transcribe {
        let name = &case.name;
        let x = render(case.n, &case.ops);
        let input = signals::fnv1a(&x);
        if input != case.input {
            diffs.push(format!("{name}: input hash {input}, want {}", case.input));
            continue;
        }
        let env = narration::envelope(&x);
        check(
            &mut diffs,
            &format!("{name}: floor"),
            exact(env.floor),
            exact(num(&case.floor)),
        );
        check(
            &mut diffs,
            &format!("{name}: pieces"),
            format!("{:?}", narration::pieces(&env, x.len())),
            format!("{:?}", case.pieces),
        );
        let mut t = Scripted {
            script: &case.script,
            calls: Vec::new(),
        };
        let opts = TranscribeOptions {
            language: case.language.clone(),
        };
        let got = narration::transcribe_narration(&x, &mut t, &opts)?;
        let calls: Vec<String> = t
            .calls
            .iter()
            .map(|(n, rate, lang, hash)| format!("{n} {rate} {lang:?} {hash}"))
            .collect();
        let want_calls: Vec<String> = case
            .calls
            .iter()
            .map(|c| format!("{} 16000 {:?} {}", c.n, Some(&c.language), c.input))
            .collect();
        check(
            &mut diffs,
            &format!("{name}: recognizer calls"),
            format!("{calls:?}"),
            format!("{want_calls:?}"),
        );
        check_words(
            &mut diffs,
            &format!("{name}: words"),
            &got.words,
            &case.words,
        );
        check(
            &mut diffs,
            &format!("{name}: looped"),
            got.looped.to_string(),
            case.looped.to_string(),
        );
        check(
            &mut diffs,
            &format!("{name}: duration"),
            exact(got.duration),
            exact(num(&case.duration)),
        );
        let mut file = WordsFile::new(case.file.clone(), MODEL, got);
        check(
            &mut diffs,
            &format!("{name}: words file"),
            narration::js_json(&file)?,
            case.json.clone(),
        );
        if let Some(c) = &case.compose {
            compose(&mut file, &x, c)?;
            check_words(
                &mut diffs,
                &format!("{name}: script words"),
                &file.words,
                &c.words,
            );
            check(
                &mut diffs,
                &format!("{name}: words file with script"),
                narration::js_json(&file)?,
                c.json.clone(),
            );
        }
    }
    report("transcribe", &diffs);
    Ok(())
}

#[test]
fn signal_functions_match_javascript() -> narration::Result<()> {
    let f: Fixture = load_json(Path::new(FIXTURE));
    let mut diffs = Vec::new();
    for case in &f.signals {
        let name = &case.name;
        let x = render(case.n, &case.ops);
        let input = signals::fnv1a(&x);
        if input != case.input {
            diffs.push(format!("{name}: input hash {input}, want {}", case.input));
            continue;
        }
        let env = narration::envelope(&x);
        let duration = x.len() as f64 / 16000.0;
        check(
            &mut diffs,
            &format!("{name}: floor"),
            exact(env.floor),
            exact(num(&case.floor)),
        );
        for (i, c) in case.snap_onsets.iter().enumerate() {
            let mut words = c.words.clone();
            narration::snap_onsets(&mut words, &env);
            check_words(
                &mut diffs,
                &format!("{name}: snapOnsets {i}"),
                &words,
                &c.out,
            );
        }
        for (i, c) in case.snap_ends.iter().enumerate() {
            let mut words = c.words.clone();
            narration::snap_ends(&mut words, &env, duration);
            check_words(&mut diffs, &format!("{name}: snapEnds {i}"), &words, &c.out);
        }
        for (i, c) in case.fit_to_sound.iter().enumerate() {
            let mut words = c.words.clone();
            narration::fit_to_sound(&mut words, &env, duration)?;
            check_words(
                &mut diffs,
                &format!("{name}: fitToSound {i}"),
                &words,
                &c.out,
            );
        }
        for c in &case.last_run {
            let got = narration::last_run(&env, c.from, c.to).map(|(a, b)| (exact(a), exact(b)));
            let want = c.out.as_ref().map(|(a, b)| (exact(num(a)), exact(num(b))));
            check(
                &mut diffs,
                &format!("{name}: lastRun {} {}", c.from, c.to),
                format!("{got:?}"),
                format!("{want:?}"),
            );
        }
        for (i, c) in case.fit_file.iter().enumerate() {
            let mut words = c.words.clone();
            let spans = c.spans.as_deref().map(cues);
            let groups = match (&spans, &c.phrase) {
                (Some(spans), Some(phrase)) => Some(PhraseGroups { spans, phrase }),
                _ => None,
            };
            narration::fit_file(&mut words, &x, groups)?;
            check_words(&mut diffs, &format!("{name}: fitFile {i}"), &words, &c.out);
        }
    }
    report("signal functions", &diffs);
    Ok(())
}

#[test]
fn word_functions_match_javascript() -> narration::Result<()> {
    let f: Fixture = load_json(Path::new(FIXTURE));
    let mut diffs = Vec::new();
    for (i, c) in f.even_out.iter().enumerate() {
        let mut words = c.words.clone();
        narration::even_out(&mut words, c.limit.unwrap_or(f64::INFINITY))?;
        check_words(&mut diffs, &format!("evenOut {i}"), &words, &c.out);
    }
    for (i, c) in f.collapse.iter().enumerate() {
        let got = narration::collapse_loops(&c.words)?;
        check_words(
            &mut diffs,
            &format!("collapseLoops {i}"),
            &got.words,
            &c.out,
        );
        check(
            &mut diffs,
            &format!("collapseLoops {i} found"),
            got.found.to_string(),
            c.found.to_string(),
        );
    }
    for (i, c) in f.align_phrases.iter().enumerate() {
        let got = narration::align_phrases(&c.words, &cues(&c.phrases))?;
        check_words(&mut diffs, &format!("alignPhrases {i}"), &got.words, &c.out);
        check(
            &mut diffs,
            &format!("alignPhrases {i} phrases"),
            format!("{:?}", got.phrase),
            format!("{:?}", c.phrase),
        );
    }
    for c in &f.find_phrase.cases {
        let got = narration::find_phrase(&f.find_phrase.words, &c.phrase, c.near)?
            .map(|h| format!("{} {} {}", exact(h.start), exact(h.end), exact(h.score)));
        let want = c.out.as_ref().map(|h| {
            format!(
                "{} {} {}",
                exact(num(&h.start)),
                exact(num(&h.end)),
                exact(num(&h.score))
            )
        });
        check(
            &mut diffs,
            &format!("findPhrase {:?} near {}", c.phrase, c.near),
            format!("{got:?}"),
            format!("{want:?}"),
        );
    }
    for c in &f.words_file {
        let got = narration::words_file(Path::new("out"), Path::new(&c.file));
        check(
            &mut diffs,
            &format!("wordsFile {:?}", c.file),
            got.to_string_lossy().into_owned(),
            c.out.clone(),
        );
    }
    report("word functions", &diffs);
    Ok(())
}

#[test]
fn spoken_words_match_javascript() -> narration::Result<()> {
    let f: Fixture = load_json(Path::new(FIXTURE));
    let s = &f.spoken;
    let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("creating a temporary directory: {e}"));
    let out_dir = dir.path().join("out");
    let voice = out_dir.join("voice");
    std::fs::create_dir_all(&voice).unwrap_or_else(|e| panic!("creating {}: {e}", voice.display()));
    for (name, text) in &s.files {
        std::fs::write(voice.join(name), text).unwrap_or_else(|e| panic!("writing {name}: {e}"));
    }
    let m = NarrationManifest {
        out_dir: out_dir.clone(),
        voiceover: Some(Voiceover {
            file: PathBuf::from(&s.manifest.voiceover.file),
            at: s.manifest.voiceover.at,
            script: None,
        }),
        scenes: s
            .manifest
            .scenes
            .iter()
            .map(|sc| SceneNarration {
                name: sc.name.clone(),
                start: sc.start,
                audio: sc.audio.as_ref().map(PathBuf::from),
                script: sc.script.as_ref().map(PathBuf::from),
            })
            .collect(),
    };
    let mut diffs = Vec::new();
    let rows = |list: &[narration::Narration]| -> Vec<String> {
        list.iter()
            .map(|n| {
                format!(
                    "{} {} {} {:?}",
                    n.file.display(),
                    exact(n.at),
                    n.label,
                    n.script.as_ref().map(|p| p.display().to_string())
                )
            })
            .collect()
    };
    let want_rows = |list: &[NarrationOut]| -> Vec<String> {
        list.iter()
            .map(|n| {
                format!(
                    "{} {} {} {:?}",
                    n.file,
                    exact(num(&n.at)),
                    n.label,
                    n.script
                )
            })
            .collect()
    };
    check(
        &mut diffs,
        "narrations",
        format!("{:?}", rows(&narration::narrations(&m))),
        format!("{:?}", want_rows(&s.narrations)),
    );
    let spoken = narration::spoken_words(&m)?;
    check_words(&mut diffs, "spokenWords", &spoken.words, &s.words);
    check(
        &mut diffs,
        "spokenWords missing",
        format!("{:?}", rows(&spoken.missing)),
        format!("{:?}", want_rows(&s.missing)),
    );
    let timeline = TimelineWords::new(&spoken.words);
    check(
        &mut diffs,
        "timeline JSON",
        narration::js_json(&timeline)?,
        s.timeline.clone(),
    );
    let path = narration::write_timeline(&out_dir, &timeline)?;
    let written = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    check(&mut diffs, "timeline file", written, s.timeline.clone());
    report("spoken words", &diffs);
    Ok(())
}
